# Sales report generator (Python 3).
import urllib.request
import urllib.error
import configparser
import ast

from utils import format_money


def load_sales(url):
    response = urllib.request.urlopen(url)
    return ast.literal_eval(response.read().decode('utf-8'))


def summarize(sales):
    totals = {}
    for region, amount in sales:
        if region in totals:
            totals[region] += amount
        else:
            totals[region] = amount
    for region, total in totals.items():
        print("%s: %s" % (region, format_money(total)))
    return totals


def main():
    config = configparser.ConfigParser()
    config.read("report.ini")
    try:
        sales = load_sales(config.get("source", "url"))
    except urllib.error.URLError as e:
        print("Could not load sales:", e)
        return
    summarize(sales)


if __name__ == "__main__":
    main()

